import{_ as a,o as r,c as d,a0 as l}from"./chunks/framework.ZoVXsKRZ.js";const b=JSON.parse('{"title":"🗺️ 各地麻将规则大全","description":"","frontmatter":{"lastUpdated":true},"headers":[],"relativePath":"skills/rules.md","filePath":"skills/rules.md","lastUpdated":1784794489000}'),e={name:"skills/rules.md"};function o(i,t,n,h,s,u){return r(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="🗺️-各地麻将规则大全" tabindex="-1">🗺️ 各地麻将规则大全 <a class="header-anchor" href="#🗺️-各地麻将规则大全" aria-label="Permalink to &quot;🗺️ 各地麻将规则大全&quot;">​</a></h1><p>中国地大物博，麻将玩法也是百花齐放。这里整理了最常见的几种麻将规则。</p><hr><h2 id="🇨🇳-广东麻将-鸡平胡" tabindex="-1">🇨🇳 广东麻将（鸡平胡） <a class="header-anchor" href="#🇨🇳-广东麻将-鸡平胡" aria-label="Permalink to &quot;🇨🇳 广东麻将（鸡平胡）&quot;">​</a></h2><p>广东地区最流行的玩法，节奏快、易上手。</p><h3 id="基本规则" tabindex="-1">基本规则 <a class="header-anchor" href="#基本规则" aria-label="Permalink to &quot;基本规则&quot;">​</a></h3><ul><li><strong>牌数</strong>：136 张（万、筒、条 + 字牌，无花牌）</li><li><strong>人数</strong>：4 人</li><li><strong>胡牌条件</strong>：4 组面子 + 1 对将牌</li></ul><h3 id="特色规则" tabindex="-1">特色规则 <a class="header-anchor" href="#特色规则" aria-label="Permalink to &quot;特色规则&quot;">​</a></h3><ul><li><strong>鸡胡</strong>：只要能胡就胡，不限制番数，最低 0 番也能胡</li><li><strong>平胡</strong>：全部由顺子组成，无刻子</li><li><strong>自摸</strong>：自己摸到胡牌，三家各付一倍</li><li><strong>点炮</strong>：别人打出的牌让你胡，点炮者付三倍（包三家）</li></ul><h3 id="番型速查" tabindex="-1">番型速查 <a class="header-anchor" href="#番型速查" aria-label="Permalink to &quot;番型速查&quot;">​</a></h3><table tabindex="0"><thead><tr><th>番型</th><th>说明</th><th>番数</th></tr></thead><tbody><tr><td>平胡</td><td>全顺子 + 非字牌将</td><td>1 番</td></tr><tr><td>碰碰胡</td><td>全刻子</td><td>2 番</td></tr><tr><td>混一色</td><td>一种花色 + 字牌</td><td>3 番</td></tr><tr><td>清一色</td><td>全部同一种花色</td><td>4 番</td></tr><tr><td>七小对</td><td>7 个对子</td><td>4 番</td></tr><tr><td>十三幺</td><td>十三种幺九牌各一张 + 任意一张成对</td><td>13 番</td></tr></tbody></table><hr><h2 id="🌶️-四川麻将-血战到底" tabindex="-1">🌶️ 四川麻将（血战到底） <a class="header-anchor" href="#🌶️-四川麻将-血战到底" aria-label="Permalink to &quot;🌶️ 四川麻将（血战到底）&quot;">​</a></h2><p>川麻以「缺一门」「血战到底」著称，刺激性极高。</p><h3 id="特色规则-1" tabindex="-1">特色规则 <a class="header-anchor" href="#特色规则-1" aria-label="Permalink to &quot;特色规则&quot;">​</a></h3><ul><li><strong>缺一门</strong>：胡牌时手牌必须缺少一种花色（万/筒/条缺一种）</li><li><strong>血战到底</strong>：有人胡牌后，剩下的人继续打到只剩最后一人</li><li><strong>刮风下雨</strong>：杠牌有特殊收益（明杠/暗杠/补杠各有说法）</li><li><strong>不可吃牌</strong>：只能碰和杠，不能吃</li></ul><h3 id="番型速查-1" tabindex="-1">番型速查 <a class="header-anchor" href="#番型速查-1" aria-label="Permalink to &quot;番型速查&quot;">​</a></h3><table tabindex="0"><thead><tr><th>番型</th><th>说明</th><th>番数</th></tr></thead><tbody><tr><td>根</td><td>四归一（杠）</td><td>1 番</td></tr><tr><td>大对子</td><td>碰碰胡</td><td>1 番</td></tr><tr><td>清一色</td><td>缺两门</td><td>2 番</td></tr><tr><td>七对</td><td>七个对子</td><td>2 番</td></tr><tr><td>龙七对</td><td>七对中含一个杠（四张相同）</td><td>3 番</td></tr><tr><td>清大对</td><td>清一色 + 碰碰胡</td><td>3 番</td></tr><tr><td>十八罗汉</td><td>四个杠 + 一对将</td><td>极罕</td></tr></tbody></table><hr><h2 id="🎌-日本麻将-立直麻将-リーチ麻雀" tabindex="-1">🎌 日本麻将（立直麻将 / リーチ麻雀） <a class="header-anchor" href="#🎌-日本麻将-立直麻将-リーチ麻雀" aria-label="Permalink to &quot;🎌 日本麻将（立直麻将 / リーチ麻雀）&quot;">​</a></h2><p>日麻以策略深度著称，近年来在国内也越来越流行。</p><h3 id="特色规则-2" tabindex="-1">特色规则 <a class="header-anchor" href="#特色规则-2" aria-label="Permalink to &quot;特色规则&quot;">​</a></h3><ul><li><strong>立直（リーチ）</strong>：听牌后可宣言进入立直状态，增加番数</li><li><strong>有番才能胡</strong>：必须满足至少一种役（番型），不能「鸡胡」</li><li><strong>振听（フリテン）</strong>：自己打过的牌不能胡别人的</li><li><strong>点数制</strong>：按番数和符数计算点数，满贯/跳满/倍满/役满</li></ul><h3 id="常见役种" tabindex="-1">常见役种 <a class="header-anchor" href="#常见役种" aria-label="Permalink to &quot;常见役种&quot;">​</a></h3><table tabindex="0"><thead><tr><th>役名</th><th>说明</th><th>番数</th></tr></thead><tbody><tr><td>立直</td><td>听牌宣言，门清状态</td><td>1 番</td></tr><tr><td>断幺九</td><td>无幺九牌和字牌</td><td>1 番</td></tr><tr><td>平和</td><td>全顺子 + 两面听</td><td>1 番</td></tr><tr><td>一杯口</td><td>两组相同的顺子</td><td>1 番</td></tr><tr><td>混一色</td><td>一种花色 + 字牌</td><td>2-3 番</td></tr><tr><td>清一色</td><td>全部同一花色</td><td>5-6 番</td></tr><tr><td>国士无双</td><td>十三种幺九牌 + 一对</td><td>役满</td></tr></tbody></table><hr><h2 id="🏘️-长沙麻将" tabindex="-1">🏘️ 长沙麻将 <a class="header-anchor" href="#🏘️-长沙麻将" aria-label="Permalink to &quot;🏘️ 长沙麻将&quot;">​</a></h2><p>湖南长沙地区的特色玩法，节奏极快。</p><h3 id="特色规则-3" tabindex="-1">特色规则 <a class="header-anchor" href="#特色规则-3" aria-label="Permalink to &quot;特色规则&quot;">​</a></h3><ul><li><strong>二五八做将</strong>：将牌必须是 2、5、8（万/筒/条均可）</li><li><strong>大开放</strong>：可吃可碰</li><li><strong>扎鸟（抓鸟）</strong>：胡牌后翻开牌山一张，按点数计算奖金倍率</li><li><strong>小胡/大胡</strong>：区分普通胡牌和特殊牌型</li></ul><hr><h2 id="🎲-东北麻将" tabindex="-1">🎲 东北麻将 <a class="header-anchor" href="#🎲-东北麻将" aria-label="Permalink to &quot;🎲 东北麻将&quot;">​</a></h2><h3 id="特色规则-4" tabindex="-1">特色规则 <a class="header-anchor" href="#特色规则-4" aria-label="Permalink to &quot;特色规则&quot;">​</a></h3><ul><li><strong>不能缺门</strong>：花色的要求与川麻相反，三种花色都要有</li><li><strong>必须有幺九</strong>：必须有 1 或 9 或字牌</li><li><strong>门前清优先</strong>：鼓励不吃不碰听牌</li></ul><hr><h2 id="💡-通用建议" tabindex="-1">💡 通用建议 <a class="header-anchor" href="#💡-通用建议" aria-label="Permalink to &quot;💡 通用建议&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">打牌前问清楚</p><p>去不同的地方打牌，第一件事一定是<strong>问清楚当地规则</strong>！同样的牌型在不同规则下可能是胡牌也可能是诈胡。特别是：</p><ul><li>有没有「缺一门」要求？</li><li>胡牌有没有番数下限？</li><li>能不能吃牌？</li><li>自摸和点炮的结算方式？</li></ul></div><hr><p><em>各地规则如有差异，以当地约定为准。有补充欢迎反馈！</em></p>',39)])])}const g=a(e,[["render",o]]);export{b as __pageData,g as default};
